; Generated by floppy/tools/fat12_to_s.py from idd5000.img; regenerate rather than edit (floppy/README.md).

; The KN5000 formatter writes these first 32 bytes: FDC_Format2HD_WriteBoot (v10/v9 0xf522f5)
; copies FDC_Format2HD_BootSectorHead (v10 0xe450da, v10/maincpu/ui_widgets/widget_descriptors.s),
; which is EB 1C 90 "Technics", this BPB and EB FE, byte for byte.  On these images the rest
; of the sector, signature word included, is zero.

; Boot sector (sector 0).  Field names: fatgen103 section 3.

Boot_Jump:		.byte	0xeb, 0x1c, 0x90
Boot_OemName:		.ascii	"Technics"
BPB_BytesPerSector:	.short	FAT12_BYTES_PER_SECTOR
BPB_SectorsPerCluster:	.byte	FAT12_SECTORS_PER_CLUSTER
BPB_ReservedSectors:	.short	FAT12_RESERVED_SECTORS
BPB_NumberOfFats:	.byte	FAT12_FATS
BPB_RootEntries:	.short	FAT12_ROOT_ENTRIES
BPB_TotalSectors16:	.short	2880
BPB_MediaDescriptor:	.byte	0xf0
BPB_SectorsPerFat:	.short	FAT12_SECTORS_PER_FAT
BPB_SectorsPerTrack:	.short	18
BPB_Heads:		.short	2
BPB_HiddenSectors:	.short	0		; DOS 3.x BPB: 16-bit count, no extended fields
Boot_Code:
	.byte	0xeb, 0xfe		; x86 `jmp $`: spins forever, the diskette does not boot a PC
	.fill	478, 1, 0
Boot_Signature:		.short	0x0000		; not 0xaa55: no PC boot signature
